mapper.select:
SELECT

FROM phone_verification
WHERE phone_verification_id =
#{phoneVerificationId}
AND member_id = #{memberId}

mapper.update:
UPDATE phone_verification
SET expires_at = #{expiredAt}
WHERE member_id = #{memberId}
  AND verified_at IS NULL
  AND expires_at > #{expiredAt}

UPDATE phone_verification
SET attempt_count = attempt_count + 1
WHERE phone_verification_id =
      #{phoneVerificationId}
  AND member_id = #{memberId}
  AND verified_at IS NULL
  AND expires_at > #{attemptedAt}
  AND attempt_count < #{maxAttempts}

UPDATE phone_verification
SET verified_at = #{verifiedAt},
    verification_token_hash =
        #{verificationTokenHash},
    token_expires_at = #{tokenExpiresAt}
WHERE phone_verification_id =
      #{phoneVerificationId}
  AND member_id = #{memberId}
  AND verified_at IS NULL
  AND expires_at > #{verifiedAt}
  AND attempt_count < #{maxAttempts}

UPDATE phone_verification
SET token_consumed_at = #{consumedAt}
WHERE phone_verification_id =
      #{phoneVerificationId}
  AND member_id = #{memberId}
  AND verification_token_hash =
      #{verificationTokenHash}
  AND verified_at IS NOT NULL
  AND token_expires_at > #{consumedAt}
  AND token_consumed_at IS NULL
